{
  "name": "软件 SPI 总线组件",
  "name_en": "Software SPI Bus Component",
  "manufacturer": "",
  "description": "一个非物理的软件组件，用 GPIO 引脚以位操作方式实现本地 SPI 总线通信。它为实验中的 SPI 外设提供基础数据传输、总线共享与关闭状态管理，但本身不是具体仪器。",
  "description_en": "A non-physical software component that implements local SPI bus communication by bit-banging GPIO pins. It provides basic data transfer, shared bus handling, and closed-state management for SPI peripherals used in experiments, but it is not a physical instrument itself.",
  "actions": [
    {
      "action_name": "auto-close",
      "description": "关闭软件 SPI 总线。",
      "description_en": "Close the software SPI bus."
    },
    {
      "action_name": "auto-transfer",
      "description": "通过软件 SPI 总线传输数据，并返回读取到的数据。",
      "description_en": "Transfer data through the software SPI bus and return the data read back."
    },
    {
      "action_name": "auto-closed",
      "description": "获取总线是否已关闭。",
      "description_en": "Get whether the bus is closed."
    }
  ],
  "tag_hints": [
    "software SPI",
    "bit-banged SPI",
    "GPIO communication",
    "local SPI bus",
    "SPI data transfer",
    "shared bus interface"
  ]
}

